// Full17 audit at exactly one recorded AR20 pose. No other AR or full table.
#include "slurry_scattering_provider.h"
#include "slurry_spd_table17.h"
#include <Eigen/Eigenvalues>
#include <fstream>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <cstdlib>
#include <cctype>
namespace sc=SlurryScattering;namespace gp=SlurryGrandPair;
constexpr double ar=20.,ti=.0049245303592113559,tj=.041010932014513654,az=1.7016960206944713;
std::string readfile(const std::string&path){std::ifstream f(path);if(!f)throw std::runtime_error("Cannot open "+path);std::ostringstream s;s<<f.rdbuf();return s.str();}
double scalar(const std::string&s,const std::string&key){auto i=s.find('"'+key+'"');if(i==std::string::npos)throw std::runtime_error("Missing "+key);i=s.find(':',i);char*end=nullptr;double x=std::strtod(s.c_str()+i+1,&end);if(end==s.c_str()+i+1||!std::isfinite(x))throw std::runtime_error("Invalid "+key);return x;}
sc::Mat17 readmatrix(const std::string&s){auto i=s.find("\"raw_full17\"");if(i==std::string::npos)throw std::runtime_error("Missing raw_full17");i=s.find('[',i);const char*p=s.c_str()+i;sc::Mat17 m;for(int k=0;k<289;++k){while(*p&&(*p=='['||*p==']'||*p==','||std::isspace(static_cast<unsigned char>(*p))))++p;char*end=nullptr;m(k/17,k%17)=std::strtod(p,&end);if(end==p||!std::isfinite(m(k/17,k%17)))throw std::runtime_error("Invalid raw matrix");p=end;}return .5*(m+m.transpose()).eval();}
void geometry_check(const std::string&s){if(std::abs(scalar(s,"aspect_ratio")-ar)>1e-12||std::abs(scalar(s,"theta_i")-ti)>1e-14||std::abs(scalar(s,"theta_j")-tj)>1e-14||std::abs(scalar(s,"phi")-az)>1e-14)throw std::runtime_error("Saved matrix is not the exact failed AR20 pose");}
double rel(const Eigen::MatrixXd&a,const Eigen::MatrixXd&b){return (a-b).norm()/std::max(b.norm(),1e-300);}
double energy(const sc::Mat17&a,const sc::Mat17&b){Eigen::GeneralizedSelfAdjointEigenSolver<sc::Mat17> e(a,b);if(e.info()!=Eigen::Success)throw std::runtime_error("Energy eigensolve failed");return (e.eigenvalues().array()-1.).abs().maxCoeff();}
struct Check{double force=0,torque=0,stress=0,energy_fd=0,power=0,power_backward=0;};
Check runtime_check(const sc::Mat17&corr,const std::array<sc::Body,2>&bodies,double actual_h){
 gp::Model model;model.metadata.kind=gp::MatrixKind::PairCorrection;model.metadata.model_id="one_pose_full17_matched_test";for(int i=0;i<17;++i)for(int j=0;j<17;++j)model.resistance[17*i+j]=corr(i,j)/ar;gp::Frame frame;frame.model_length=frame.solver_length=ar;
 gp::Inputs x;const auto basis=sc::strain_basis();sc::Mat3 strain=sc::Mat3::Zero();for(int k=0;k<5;++k)strain+=.1*std::cos(.57*(k+1))*basis[k]/ar;
 const sc::Vec3 middle(0.,0.,actual_h/2),translation(.1,-.03,.07),omega(.04,.02,-.05);
 // A physical common rigid motion evaluated relative to the actual centers.
 for(int i=0;i<2;++i){const sc::Vec3 u=translation+omega.cross(bodies[i].center-middle)/ar;const sc::Vec3 background=strain*(bodies[i].center-middle);for(int k=0;k<3;++k){x.velocity[6*i+k]=u[k];x.background[6*i+k]=background[k];x.velocity[6*i+3+k]=omega[k];}}
 for(int i=0;i<3;++i)for(int j=0;j<3;++j)x.strain[3*i+j]=strain(i,j);
 const auto result=gp::evaluate(model,frame,x);const auto embed=gp::embed(frame,x.background,x.image_nonaffine);const auto z=gp::state(embed,x.velocity,gp::strain_coordinates(x.strain));Eigen::Matrix<double,17,1> eigen_z;for(int i=0;i<17;++i)eigen_z[i]=z[i];const Eigen::Matrix<double,17,1> response=corr*eigen_z;Check out;
 for(int k=0;k<3;++k){out.force=std::max(out.force,std::max(std::abs(result.force_i[k]+response[k]),std::abs(result.force_j[k]+response[6+k])));out.torque=std::max(out.torque,std::max(std::abs(result.torque_i[k]+ar*response[3+k]),std::abs(result.torque_j[k]+ar*response[9+k])));}
 for(int k=0;k<5;++k)out.stress=std::max(out.stress,std::abs(result.stress_coordinates[k]-ar*response[12+k]));
 auto quadratic=[&](const gp::Inputs& state)->long double {const auto zz=gp::state(embed,state.velocity,gp::strain_coordinates(state.strain));long double sum=0;for(int i=0;i<17;++i)for(int j=0;j<17;++j)sum+=static_cast<long double>(zz[i])*corr(i,j)*zz[j];return sum/2;};
 const long double reference_power=2*quadratic(x);const double power_error=std::abs(static_cast<long double>(result.power)-reference_power);out.power=power_error/std::max(1.,static_cast<double>(std::abs(reference_power)));out.power_backward=power_error/std::max(1.,corr.norm()*eigen_z.squaredNorm());
 // The quadratic has no finite-difference truncation error. Long-double accumulation
 // and a finite step avoid cancellation in common-motion states at narrow gaps.
 const double step=1e-3,scale=std::max(1.,static_cast<double>(std::abs(quadratic(x))));for(int k=0;k<12;++k){auto plus=x,minus=x;plus.velocity[k]+=step;minus.velocity[k]-=step;const double fd=static_cast<double>((quadratic(plus)-quadratic(minus))/(2*step));out.energy_fd=std::max(out.energy_fd,std::abs(fd-result.gradient[k])/scale);}
 // Hold nonaffine center velocities fixed: background remains unchanged.
 for(int k=0;k<5;++k){auto plus=x,minus=x;for(int j=0;j<9;++j){plus.strain[j]+=step*gp::strain_basis()[k][j]/ar;minus.strain[j]-=step*gp::strain_basis()[k][j]/ar;}const double fd=static_cast<double>((quadratic(plus)-quadratic(minus))/(2*step));out.energy_fd=std::max(out.energy_fd,std::abs(fd-result.stress_coordinates[k]/ar)/scale);}
 out.force/=std::max(1.,corr.norm());out.torque/=std::max(1.,ar*corr.norm());out.stress/=std::max(1.,ar*corr.norm());return out;
}
int main(int argc,char**argv){try{
 if(argc<2)throw std::runtime_error("Usage: check_ar20_full17_matching anchor_probe.json [heldout_probe.json ...]");const auto source=readfile(argv[1]);geometry_check(source);const double anchor=scalar(source,"h_over_c");
 const std::array<sc::Vec3,2> axes{{{std::sin(ti),0.,std::cos(ti)},{std::sin(tj)*std::cos(az),std::sin(tj)*std::sin(az),std::cos(tj)}}};sc::Provider provider;provider.basis.aspect_ratio=ar;provider.hybrid=true;provider.hybrid_version=4;provider.anchor_count=2;provider.anchor_gaps={anchor,2*anchor,0.};SlurrySPDCoordinates17::Shape shape(ar);provider.isolated_local=SlurrySPDCoordinates::Shape(ar).isolated_local;
 const sc::Mat17 target=readmatrix(source),self=shape.self(axes,anchor),singular=provider.near17(axes,anchor),residual=target-self-singular;sc::AnchorResiduals17 saved;for(int i=0;i<17;++i)for(int j=0;j<17;++j)saved.values[0][17*i+j]=residual(i,j);
 std::vector<std::pair<double,sc::Mat17>> references;for(int k=2;k<argc;++k){const auto text=readfile(argv[k]);geometry_check(text);references.push_back({scalar(text,"h_over_c"),readmatrix(text)});}
 std::vector<double> gaps={anchor,.25,.02,1./150.};for(const auto&r:references){bool exists=false;for(double h:gaps)exists|=std::abs(h-r.first)<1e-13;if(!exists)gaps.push_back(r.first);}
 bool pass=true,overlap_pass=true;int overlap_count=0;constexpr double tolerance=.01;
 std::cout<<std::setprecision(17)<<"{\n\"method\":\"ar20_full17_saved_anchor_v4_matching_audit\",\n\"physical_accuracy_qualified\":false,\n\"note\":\"No11-reduction. Algebra/passivity/153-entry encoding gates only; physical source and model overlap accuracy require independently converged references. Intrinsic stress is differentiated at fixed center-nonaffine velocities.\",\n\"anchor_gap_over_c\":"<<anchor<<",\n\"queries\":[\n";
 for(std::size_t index=0;index<gaps.size();++index){const double h=gaps[index];const auto bodies=sc::geometry(axes,h,ar);const sc::Mat17 correction=provider.matched_near17(axes,h,saved),total=shape.self(axes,h)+correction,lead=provider.near17(axes,h);Eigen::SelfAdjointEigenSolver<sc::Mat17> eig(total);if(eig.info()!=Eigen::Success)throw std::runtime_error("Full17 eigensolve failed");const bool positive=eig.eigenvalues().minCoeff()>0.;pass&=positive;const auto runtime=runtime_check(correction,bodies,h);pass&=runtime.energy_fd<1e-7&&runtime.force<1e-12&&runtime.torque<1e-12&&runtime.stress<1e-12&&runtime.power_backward<1e-12;
 std::cout<<(index?",\n":"")<<"{\"h_over_c\":"<<h<<",\"gap_nm\":"<<150*h<<",\"runtime_branch\":\""<<(h>=anchor?"direct_stokes":"matched_near")<<"\",\"matching_evaluation\":\""<<(h>anchor?"upward_continuation_for_overlap_only":"near_formula")<<"\",\"minimum_full17_eigenvalue\":"<<eig.eigenvalues().minCoeff()<<",\"full17_spd\":"<<(positive?"true":"false")<<",\"constant_residual_relative_error\":"<<rel(correction-lead,residual)<<",\"force_mapping_scaled_error\":"<<runtime.force<<",\"torque_mapping_scaled_error\":"<<runtime.torque<<",\"stresslet_mapping_scaled_error\":"<<runtime.stress<<",\"runtime_power_relative_error\":"<<runtime.power<<",\"runtime_power_backward_scaled_error\":"<<runtime.power_backward<<",\"runtime_energy_derivative_scaled_error\":"<<runtime.energy_fd;
 if(index==0){const double error=energy(total,target);pass&=error<1e-9;std::cout<<",\"anchor_full17_reconstruction_worst_energy_error\":"<<error;}
 if(positive){const sc::Mat17 logm=SlurrySPDTable17::encode_total(shape,axes,h,total);std::stringstream storage;storage<<std::setprecision(17);int count=0;for(int i=0;i<17;++i)for(int j=0;j<=i;++j){storage<<logm(i,j)<<' ';++count;}sc::Mat17 decoded;for(int i=0;i<17;++i)for(int j=0;j<=i;++j){double v;if(!(storage>>v))throw std::runtime_error("153-entry decode failed");decoded(i,j)=decoded(j,i)=v;}const sc::Mat17 roundtrip=SlurrySPDTable17::decode_total(shape,axes,h,decoded);const double error=energy(roundtrip,total);pass&=error<1e-9&&count==153;std::cout<<",\"encoded_values\":"<<count<<",\"log153_roundtrip_worst_energy_error\":"<<error<<",\"log153_roundtrip_force_torque_operator_error\":"<<rel(roundtrip.topRows<12>(),total.topRows<12>())<<",\"log153_roundtrip_intrinsic_stress_operator_error\":"<<rel(roundtrip.bottomRows<5>(),total.bottomRows<5>());}
 for(const auto&r:references)if(std::abs(r.first-h)<1e-13){Eigen::LLT<sc::Mat17> check(r.second);if(check.info()!=Eigen::Success)throw std::runtime_error("Held-out reference not SPD");const double error=energy(total,r.second);const bool independent_gap=std::abs(h-anchor)>1e-13;if(independent_gap){++overlap_count;overlap_pass&=error<=tolerance;}std::cout<<",\"supplied_direct_full17_worst_energy_error\":"<<error<<",\"counts_as_heldout_gap\":"<<(independent_gap?"true":"false")<<",\"model_overlap_tolerance\":"<<tolerance<<",\"model_overlap_error_gate_passed\":"<<(error<=tolerance?"true":"false");}
 std::cout<<'}';}
 std::cout<<"\n],\n\"actual_geometry_hardfloor_checks\":[\n";const double floor_h=1./150.;const sc::Mat17 floor_correction=provider.matched_near17(axes,floor_h,saved);const std::array<double,3> actual_nm{{0.,.5,-.15}};
 for(std::size_t k=0;k<actual_nm.size();++k){const double h=actual_nm[k]/150.;const auto bodies=sc::geometry(axes,h,ar);const sc::Mat17 total=provider.isolated(bodies)+floor_correction;Eigen::SelfAdjointEigenSolver<sc::Mat17> e(total);if(e.info()!=Eigen::Success)throw std::runtime_error("Subfloor eigensolve failed");const bool positive=e.eigenvalues().minCoeff()>0.;const auto runtime=runtime_check(floor_correction,bodies,h);pass&=positive&&runtime.energy_fd<1e-7;std::cout<<(k?",\n":"")<<"{\"actual_gap_nm\":"<<actual_nm[k]<<",\"effective_gap_nm\":1,\"scope\":\""<<(h<0?"overlap_robustness_only_no_fluid_BVP":"direct_center_coordinate_regularization_no_midpoint_lift")<<"\",\"minimum_full17_eigenvalue\":"<<e.eigenvalues().minCoeff()<<",\"full17_spd\":"<<(positive?"true":"false")<<",\"runtime_energy_derivative_scaled_error\":"<<runtime.energy_fd<<'}';}
 std::cout<<"\n],\n\"algebra_passivity_encoding_gate_passed\":"<<(pass?"true":"false")<<",\n\"heldout_gap_count\":"<<overlap_count<<",\n\"physical_overlap_error_gate_passed\":"<<(overlap_count?(overlap_pass?"true":"false"):"null")<<"\n}\n";return pass&&overlap_pass?0:2;
 }catch(const std::exception&e){std::cerr<<"AR20full17 matching audit: "<<e.what()<<'\n';return 1;}}
